\label{question:yau}
If $\Lambda\subset\mathbb S^n$ is closed, contains at least two points, and
satisfies
\begin{equation}\label{eq:dimension}
 \dim_{\mathrm H}\Lambda<\frac{n-2}{2},
\end{equation}
does $\mathbb S^n\setminus\Lambda$ admit a complete metric conformal to
$g_{\mathrm{rd}}$ with scalar curvature $n(n-1)$?

\label{pot:cover}
Let $E\subset\mathbb R^n$ be compact, with $\mathcal H^\beta(E)=0$, and let
$\varepsilon,d>0$.  There is a finite family of balls
$B(y_i,r_i)$, with $y_i\in E$, such that:
\begin{enumerate}
\item their closures are pairwise disjoint;
\item $E\subset\bigcup_i B(y_i,5r_i)$;
\item $\max_i r_i<d$ and $\sum_i r_i^\beta<\varepsilon$;
\item for every $x\in\mathbb R^n$ and $R>0$,
\begin{equation}\label{pot:packing}
 \sum_{\substack{y_i\in B(x,R)\\r_i\le R}}r_i^\beta
 \le C(n,\beta)R^\beta.
\end{equation}
\end{enumerate}
If $E\subset U$ for an open set $U$, the family can also be chosen
so that $B(y_i,10r_i)\subset U$ for every $i$.

\label{pot:endpoint}
The potentials in \eqref{pot:tails} satisfy
\begin{equation}\label{pot:endpointineq}
 \mathcal I_2(h^p)\le C\delta h
 \qquad\text{on }\mathbb R^n,
\end{equation}
and
\begin{equation}\label{pot:mass}
 \int_{\mathbb R^n}h^p\,\mathrm d x\le C\delta Q.
\end{equation}

\label{pot:positive}
Each $h_i$ is the Newtonian potential of a positive finite measure.
If $V\ge0$ satisfies $\sup_x\mathcal I_2V(x)\le L$ and
$W=\mathcal I_2\mu$ for a positive measure $\mu$, then
\begin{equation}\label{pot:3Goperator}
 \mathcal I_2(VW)(x)\le C_nLW(x)
\end{equation}
wherever $W(x)$ is finite.

\label{pot:relative}
For each index $i$ and any positive Newtonian potential $W$,
\begin{equation}\label{pot:singlemultiplier}
 \mathcal I_2(h_i^{p-1}W)\le C_n\delta W.
\end{equation}

The radial Newtonian formula gives
\begin{equation}\label{pot:singleKato}
 \sup_x\mathcal I_2(h_i^{p-1})(x)
 =\frac{4\eta^2r_i^2}{n-2}
       \int_0^\infty\frac{t\,\mathrm d t}{(\rho_i^2+t^2)^2}
 =\frac\delta a.
\end{equation}
The integral converges even when $h_i^{p-1}$ has infinite total
mass. Lemma~\ref{pot:positive} now proves
\eqref{pot:singlemultiplier}.

\label{pot:oldrepresentation}
Let $u_0$ be the positive round conformal factor of a finite-ended
solution with puncture set $F$ and Delaunay asymptotics.  Then
$u_0\in L^p(\mathbb S^n)$ and
\begin{equation}\label{eq:finite-distribution}
 \mathcal A_{\mathrm{rd}}u_0=\kappa u_0^p\qquad\text{in }\mathcal D'(\mathbb S^n).
\end{equation}
In particular, the equation has no Dirac mass at a puncture.
If the stereographic pole lies outside $F$, the flat conformal
factor $U_0=\vartheta u_0$ satisfies $U_0^p\in L^1(\mathbb R^n)$ and
\begin{equation}\label{pot:oldnewton}
 U_0=\kappa\mathcal I_2(U_0^p)
 \qquad\text{on }\mathbb R^n\setminus F.
\end{equation}
Consequently,
\begin{equation}\label{pot:oldmultiplier}
 \mathcal I_2(h_i^{p-1}U_0)\le C_n\delta U_0,
\end{equation}
with a constant independent of $U_0$.

\label{in:radial-derivative}\label{in:ode}
For every fixed integer $m\geq0$,
\begin{equation}\label{in:radial-loss}
 |\partial_t^m\partial_bv_B(t)|
       \leq C_m(1+t)v_B(t),\qquad t\geq0.
\end{equation}
For $Q_B=\kappa pU_B^q$, the corresponding scaled H\"older estimates are
\begin{align}
 r^2|Q_B|_{0,\theta;r}
   &\leq C\min\{1,s^2e^{2t}\},\label{in:potential}\\
 r^2|\partial_bQ_B|_{0,\theta;r}
   &\leq C(1+t)\min\{1,s^2e^{2t}\}.
       \label{in:potential-derivative}
\end{align}
The constants are uniform as the neck shrinks and for the phases
selected by \eqref{in:cauchy}.

\label{in:family}
Set $\vartheta_*=B_*\rho^{2a}/A$ and $\phi=B_*\psi$, with
$\psi\in\Pi_{\mathrm{hi}}C^{2,\theta}(\mathbb S^{n-1})$.
Suppose $|\boldsymbol z|\rho$ lies in the fixed neighborhood of
\eqref{in:inverse}. If $s$, $\vartheta_*$, $AB_*$, and
$\sqrt{\vartheta_*}\|\psi\|_{C^{2,\theta}}$ are sufficiently small,
there is a unique small $W\in X_{\mu_3}$, with zero high-mode boundary
trace, such that
\begin{equation}\label{in:family-equation}
 I=\mathcal T_{\boldsymbol z}U_B+H_\phi+W
\end{equation}
is a positive solution of \eqref{eq:flat}. The correction is
continuously differentiable in $(b,\boldsymbol c,\psi)$ with values in
$X_{\mu_1}$, and its boundary Cauchy data are continuously differentiable
in the usual boundary spaces. Uniformly on a fixed small parameter
neighborhood,
\begin{align}
 \|W\|_{X_{\mu_3}}
   &\leq Cs^{2-\mu_3}B_*\|\psi\|_{C^{2,\theta}},
       \label{in:w-size}\\
 \|\partial_bW\|_{X_{\mu_2}}
   &\leq C(1+\ell_s)s^{2-\mu_2}B_*\|\psi\|_{C^{2,\theta}},
       \label{in:w-b}\\
 \|\partial_{\boldsymbol c}W\|_{X_{\mu_3}}
   &\leq Cs^{2-\mu_3}B_*\|\psi\|_{C^{2,\theta}},
       \label{in:w-c}\\
 \|D_\psi W\|_{\Pi_{\mathrm{hi}}C^{2,\theta}\to X_{\mu_3}}
   &\leq Cs^{2-\mu_3}B_*.
       \label{in:w-psi}
\end{align}
More precisely, if $\mathcal D_{\mathrm{in}}$ is the harmonic
Dirichlet-to-Neumann operator on the unit ball, then
$$
\begin{aligned}
 B_*^{-1}\Pi_{\mathrm{hi}}
       \bigl(I-\mathcal T_{\boldsymbol z}U_B\bigr)|_{r=\rho}&=\psi,\\
 B_*^{-1}\Pi_{\mathrm{hi}}\rho\partial_r
       \bigl(I-\mathcal T_{\boldsymbol z}U_B\bigr)|_{r=\rho}
  &=\mathcal D_{\mathrm{in}}\psi+\mathcal E(b,\boldsymbol c,\psi),
\end{aligned}
$$
where $\mathcal D_{\mathrm{in}}$ has eigenvalue $\ell$ on degree
$\ell\geq2$, and $\mathcal E$ is a small $C^1$ error with the bounds
induced by \eqref{in:w-size}--\eqref{in:w-psi} after division by $B_*$.

\label{old:poisson}
For all $x\in D_N$,
\begin{equation}\label{old:poisson-bound}
 |P_Ng(x)|\leq C_n\sum_i
   \frac{b_i\rho_i^{n-2}}{(\rho_i^2+|x-y_i|^2)^{(n-2)/2}}
      +C_{\rm old}q_g.
\end{equation}
Its fixed old-collar $C^{2,\theta}$ norm is at most
$C_{\rm old}q_g$. The same pointwise envelope controls scaled local
$C^{2,\theta}$ norms on the new collars and on interior patches
whose size is a fixed small multiple of their distance to the holes,
capped at a fixed old radius.

\label{old:product-dtn}
Let $\mathcal D$ act on spherical degree $\ell$ as multiplication by
$-(\ell+2a)$. For sufficiently small universal $\nu$,
\begin{equation}\label{old:dtn-comparison}
 g\longmapsto(\rho_i\partial_{R_i}P_Ng|_{\Gamma_i})_i
  =\operatorname{diag}(\mathcal D)+O(\nu^{2a})+\mathcal R_{\rm old}
   :\mathcal B\longrightarrow\mathcal B_1.
\end{equation}
For each fixed old problem and each $\varepsilon>0$, the operator
$\mathcal R_{\rm old}$ has norm at most $\varepsilon$ if the largest
original radius and $Q$ are sufficiently small. Those choices may
depend on the old problem, $\nu$, and $\varepsilon$.

\label{ext:structural}
Let $G_N[F,\xi]$ denote the inverse with zero trace on the new spheres,
source $F$, and old interface forcing $\xi$ as in
\eqref{old:linear-boundary-problem}; write $G_NF=G_N[F,0]=G_N^0F$.
Choose $r_0$ and $A_0$ after fixing the old data and $\eta$.
After reducing the radius and coefficient bounds, for $W=\Phi$ and each
$\Psi_i$,
\begin{align}\label{eq:structural}
 \left\lVertG_N(V_{\mathbf p} f)\right\rVert_{X_W}&\leq(C\delta+o_0(1))\left\lVertf\right\rVert_{X_W},
 \\
 \left\lVertG_N\mathcal R_{\mathbf p}\right\rVert_{X_W}&\leq C\delta.
 \nonumber
\end{align}
For every fixed smooth multiplier $m$,
$\|G_N(mf)\|_{X_W}\leq C_{0,m}\|f\|_{X_W}$.
For $\|\dot{\mathbf p}\|_{\mathcal E_N}\leq1$, the parameter derivatives satisfy
\begin{equation}\label{eq:structural-derivatives}
 \|G_N(D_{\mathbf p}V_{\mathbf p}[\dot{\mathbf p}]f)\|_{X_W}
       \leq C_R\delta^2\|f\|_{X_W},\qquad
 \|G_ND_{\mathbf p}\mathcal R_{\mathbf p}[\dot{\mathbf p}]\|_{X_W}
       \leq C_R\delta^2.
\end{equation}
The interface forcing obeys
\begin{equation}\label{eq:interface-weighted-bound}
 \|G_N[0,\xi]\|_{X_W}
       \leq C_0 b_W^{-1}\|\xi\|_{C^{1,\theta}(\Sigma)},
 \qquad b_\Phi=b,\quad b_{\Psi_i}=1.
\end{equation}
Here the old-dependent constants are uniform in the new configuration.

\label{ext:family}
For a sufficiently small universal $\eta$ and sufficiently small
old-dependent radius and coefficient bounds, \eqref{eq:exterior-fixedpoint}
has a unique solution in a ball $C\delta$ of $X^0$, jointly $C^1$ in
$\mathbf p$. Uniformly on $\left\lVert\mathbf p\right\rVert\leq Rk$,
\begin{align}\label{eq:v-estimates}
 \left\lVertv\right\rVert_{X_\Phi}+\max_i\left\lVertv\right\rVert_{X_{\Psi_i}}&\leq C\delta,
 \\
 \left\lVert\dot v\right\rVert_{X_\Phi}&\leq C(\delta\nu^{2a}+\delta^2),&
 \max_i\left\lVert\dot v\right\rVert_{X_{\Psi_i}}&\leq C\delta.
 \nonumber
\end{align}
Moreover
\begin{equation}\label{eq:exterior-Cauchy}
 \max_i\left(\left\lVert\rho_i\partial_{R_i}v/B_i\right\rVert_{C^{1,\theta}}
 +\left\lVertD_{\mathbf p}(\rho_i\partial_{R_i}v/B_i)\right\rVert_{\mathcal E_N\to C^{1,\theta}}\right)
 \leq C\delta.
\end{equation}
The exterior Jacobi problem has zero kernel among fields with zero
full trace on the new spheres, old radial coefficient vector in
$\mathcal W'$, and physical remainder decaying at rate $d_-$ on
every eliminated old tail.

\label{match:linear}
$L$ is an isomorphism from $\mathcal E_N$ to the target product space.
Its inverse norm is independent of $N$ and the radii.

\label{match:estimate}
On $\left\lVert\mathbf p\right\rVert\leq Rk$,
\begin{align}\label{eq:mismatch-estimates}
 \left\lVert\mathcal M(0)\right\rVert&\leq C_*k+o_0(1),
 \\
 \left\lVertD\mathcal M-L\right\rVert&\leq C_R(\nu+s^{2-\mu_3})+o_0(1),
 \nonumber
\end{align}
The baseline constant $C_*$ is chosen independently of $R$.
